import RNA, random, multiprocessing as mp, time, sys
target='.((.((.....(((((...((.(((.........................))).))...))).))...)).)).(((..(((..((.......((....)).......)))))......))).(((((.......(((..((..(((..((.(((...............)))..))..)))..)).)))..))..))).'
def dist(s): return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)
def worker(seed):
    random.seed(seed)
    best=None;best_d=999
    deadline=time.time()+150
    while time.time()<deadline:
        start=''.join(random.choice('ACGU') for _ in range(200))
        seq,d=RNA.inverse_fold(start,target)
        if d==0:
            dd=dist(seq)
            if dd==0:
                return seq
            if dd<best_d:
                best_d=dd;best=seq
    return (best,best_d) if best else None
if __name__=='__main__':
    with mp.Pool(8) as p:
        results=p.imap_unordered(worker, range(80))
        for r in results:
            if r is None: continue
            if isinstance(r,str):
                print('SOLVED',r,flush=True); p.terminate(); break
            else:
                seq,d=r
                print('best',d,flush=True)

